mapper.sql:
SELECT ea.id, ea.channel_id AS channelId, ec.channel_name AS channelName, ea.channel_user_id AS channelUserId, cu.user_name AS channelUserName, ea.business_type AS businessType, ea.cost_type AS costType, ea.amount, ea.remark, creator.name AS createUserName, DATE_FORMAT(ea.create_time, '%Y-%m-%d %H:%i') AS createTime FROM employee_advance ea LEFT JOIN employee_channel ec ON ec.id = ea.channel_id AND ec.enterprise_id = ea.enterprise_id AND ec.deleted = 1 LEFT JOIN channel_user cu ON cu.id = ea.channel_user_id AND cu.enterprise_id = ea.enterprise_id AND cu.deleted = 1 LEFT JOIN account creator ON creator.id = ea.create_by AND (creator.enterprise_id = ea.enterprise_id OR creator.account_type = 1) WHERE ea.enterprise_id = #{enterpriseId} AND ea.deleted = 1
AND ea.channel_id = #{request.channelId}
AND ea.channel_user_id = #{request.channelUserId}
ORDER BY ea.create_time DESC, ea.id DESC

mapper.select:
SELECT COALESCE(SUM(CASE WHEN ea.trans_type = 1 THEN ea.amount ELSE 0 END), 0) AS totalAdvanceAmount,
       COALESCE(SUM(CASE WHEN ea.trans_type = 2 THEN ea.amount ELSE 0 END), 0) AS totalRepaymentAmount
FROM employee_advance ea
WHERE ea.enterprise_id = #{enterpriseId}
  AND ea.channel_user_id = #{channelUserId}
  AND ea.deleted = 1

SELECT ea.id, creator.name AS createUserName, ea.business_type AS businessType, ea.cost_type AS costType, DATE_FORMAT(ea.create_time, '%Y-%m-%d %H:%i') AS createTime, ea.remark, CASE WHEN ea.trans_type = 1 THEN -ea.amount ELSE ea.amount END AS amount FROM employee_advance ea LEFT JOIN account creator ON creator.id = ea.create_by AND (creator.enterprise_id = ea.enterprise_id OR creator.account_type = 1) WHERE ea.enterprise_id = #{enterpriseId} AND ea.channel_user_id = #{channelUserId} AND ea.deleted = 1
AND ea.trans_type = #{request.transType}
ORDER BY ea.create_time DESC, ea.id DESC

SELECT channel_user_id AS channelUserId, COALESCE(SUM(CASE WHEN business_type = 'companyAdvance' THEN amount ELSE 0 END), 0) AS companyAdvanceAmount, COALESCE(SUM(CASE WHEN business_type = 'companyAdvance' AND cost_type = '3' THEN amount ELSE 0 END), 0) AS wageAdvanceAmount FROM employee_advance WHERE enterprise_id = #{enterpriseId} AND deleted = 1 AND channel_user_id IN
#{channelUserId}
GROUP BY channel_user_id

SELECT id, channel_id, channel_user_id, enterprise_id, business_type, cost_type,
       amount, remark, trans_type, source_type, import_record_id, import_row_no,
       transaction_no, deleted, create_by, create_time, update_by, update_time
FROM employee_advance
WHERE enterprise_id = #{enterpriseId}
  AND channel_id = #{channelId}
  AND channel_user_id = #{channelUserId}
  AND cost_type = #{costType}
  AND trans_type = 1
  AND deleted = 1
ORDER BY create_time ASC, id ASC
FOR UPDATE

SELECT id, channel_id, channel_user_id, enterprise_id, business_type, cost_type, amount, remark, trans_type, source_type, import_record_id, import_row_no, transaction_no, deleted, create_by, create_time, update_by, update_time FROM employee_advance WHERE enterprise_id = #{enterpriseId} AND channel_user_id IN
#{channelUserId}
AND trans_type = 1 AND deleted = 1 ORDER BY channel_user_id ASC, create_time ASC, id ASC FOR UPDATE

SELECT channel_user_id AS channelUserId, COALESCE(SUM(amount), 0) AS accountSettledAmount FROM employee_advance WHERE enterprise_id = #{enterpriseId} AND deleted = 1 AND business_type = 'accountSettled' AND channel_user_id IN
#{channelUserId}
GROUP BY channel_user_id
